using FAQManagement.DbContexts; using FAQManagement.Entity; using FAQManagement.Interfaces; using FAQManagement.Model; using Microsoft.EntityFrameworkCore; namespace FAQManagement.Services { public class FAQService:IFAQService { private readonly FAQManagementContext _dbContext; public FAQService(FAQManagementContext dbContext,IConfiguration configuration){_dbContext=dbContext;} public async Task<Result<List<FAQ>>> GetAll(){var r=new Result<List<FAQ>>();try{r.SetData(await _dbContext.FAQs.AsNoTracking().Where(x=>!x.IsDeleted).ToListAsync());r.SetMessage("İşlem başarı ile gerçekleşti.");}catch(Exception ex){r.SetIsSuccess(false);r.SetMessage(ex.Message);}return r;} public async Task<Result<PagingResult<PagedList<FAQ>>>> Paginate(PagingParameter p){var r=new Result<PagingResult<PagedList<FAQ>>>();try{var q=_dbContext.FAQs.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(p.FilterText)){var f=p.FilterText.ToLower();q=q.Where(x=>x.Header.ToLower().Contains(f)||x.HeaderEn.ToLower().Contains(f)||x.Content.ToLower().Contains(f)||x.ContentEn.ToLower().Contains(f));}if(!string.IsNullOrWhiteSpace(p.Header))q=q.Where(x=>x.Header.ToLower().Contains(p.Header.ToLower()));if(!string.IsNullOrWhiteSpace(p.HeaderEn))q=q.Where(x=>x.HeaderEn.ToLower().Contains(p.HeaderEn.ToLower()));if(p.IsDeleted.HasValue)q=q.Where(x=>x.IsDeleted==p.IsDeleted);var page=PagedList<FAQ>.ToPagedList(q.OrderByDescending(x=>x.Id),p.PageNumber,p.PageSize);r.SetData(new PagingResult<PagedList<FAQ>>{Items=page,TotalCount=page.TotalCount});r.SetMessage("İşlem başarı ile gerçekleşti.");}catch(Exception ex){r.SetIsSuccess(false);r.SetMessage(ex.Message);}return r;} public async Task<Result<FAQ>> Save(FAQ item){var r=new Result<FAQ>();try{item.Id=0;item.IsDeleted=false;_dbContext.FAQs.Add(item);await _dbContext.SaveChangesAsync();r.SetData(item);r.SetMessage("İşlem başarı ile gerçekleşti.");}catch(Exception ex){r.SetIsSuccess(false);r.SetMessage(ex.Message);}return r;} public async Task<Result<FAQ>> Update(FAQ item){var r=new Result<FAQ>();try{var db=await _dbContext.FAQs.FirstOrDefaultAsync(x=>x.Id==item.Id);if(db==null){r.SetIsSuccess(false);r.SetMessage("Kayıt bulunamadı.");return r;}db.Header=item.Header;db.HeaderEn=item.HeaderEn;db.Content=item.Content;db.ContentEn=item.ContentEn;await _dbContext.SaveChangesAsync();r.SetData(db);r.SetMessage("İşlem başarı ile gerçekleşti.");}catch(Exception ex){r.SetIsSuccess(false);r.SetMessage(ex.Message);}return r;} public async Task<Result<FAQ>> Delete(long id){var r=new Result<FAQ>();try{var db=await _dbContext.FAQs.FirstOrDefaultAsync(x=>x.Id==id);if(db==null){r.SetIsSuccess(false);r.SetMessage("Kayıt bulunamadı.");return r;}db.IsDeleted=true;await _dbContext.SaveChangesAsync();r.SetData(db);r.SetMessage("İşlem başarı ile gerçekleşti.");}catch(Exception ex){r.SetIsSuccess(false);r.SetMessage(ex.Message);}return r;} } }